$locations |
ForEach-Object {
    $location = $_
    $tables = if ($location -eq 'mwa') {$mwa_tables} else {$mps_tables}

    $tables | 
    Foreach-Object {
        # print item
        $table_name = $_.ToLower()
        write-output $location + $_

        # build the dbt macro command
        $dbt_command = "dbt run-operation generate_base_models_pms --args '{pms: envestnet, pms_location: " + $location + ", table_name: " + $table_name + "}'"
        write-output $dbt_command

        # build the output file name
        $out_file = "~/Documents/GitHub/dbt-snf/models/base/pms/envestnet_" + $location + "/envestnet_" + $location + "_history__base_" + $table_name + ".sql"
        write-output $out_file

        # execute dbt macro command
        $output_data = Invoke-Expression $dbt_command

        # redirect the above output to out_file
        $output_data | Select-Object -skip 13 | Out-File -FilePath $out_file 
        # $output_data | Out-File -FilePath $out_file 
    }
}